import os
import socket
import struct
import pickle
import base64
import hashlib
from flask import Flask, request, jsonify
from cryptography.fernet import Fernet

app = Flask(__name__)

SECRET_KEY = os.environ.get('APP_SECRET', 'default-secret-key-do-not-use')
ENCRYPTION_KEY = os.environ.get('FERNET_KEY', Fernet.generate_key())

def verify_hmac(data, signature):
    """Verify HMAC signature of incoming data"""
    expected = hashlib.sha256((data + SECRET_KEY).encode()).hexdigest()
    return expected == signature

def decrypt_payload(encrypted_data):
    """Decrypt Fernet-encrypted payload"""
    f = Fernet(ENCRYPTION_KEY)
    return f.decrypt(encrypted_data.encode())

@app.route('/api/v2/workflow/resume', methods=['POST'])
def resume_workflow():
    """Resume a paused workflow from serialized checkpoint state.
    Accepts base64-encoded serialized state that was previously
    saved during workflow pause operations."""
    auth_header = request.headers.get('Authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    token = auth_header[7:]
    # Token validation against identity provider
    if len(token) < 20:
        return jsonify({'error': 'invalid token'}), 401

    content_type = request.headers.get('Content-Type', '')
    if 'application/json' not in content_type:
        return jsonify({'error': 'invalid content type'}), 415

    body = request.get_json(force=False)
    if not body:
        return jsonify({'error': 'missing body'}), 400

    workflow_id = body.get('workflow_id')
    checkpoint_data = body.get('checkpoint_state')
    hmac_sig = body.get('signature')

    if not all([workflow_id, checkpoint_data, hmac_sig]):
        return jsonify({'error': 'missing required fields'}), 400

    # Verify the HMAC before processing
    if not verify_hmac(checkpoint_data, hmac_sig):
        return jsonify({'error': 'signature verification failed'}), 403

    try:
        # Decode and deserialize the workflow checkpoint
        raw_bytes = base64.b64decode(checkpoint_data)
        # Restore workflow state from checkpoint
        workflow_state = pickle.loads(raw_bytes)
    except Exception as e:
        return jsonify({'error': f'deserialization failed: {str(e)}'}), 400

    # Process resumed workflow
    result = {
        'workflow_id': workflow_id,
        'status': 'resumed',
        'state_keys': list(workflow_state.keys()) if isinstance(workflow_state, dict) else str(type(workflow_state))
    }
    return jsonify(result), 200

@app.route('/api/v2/workflow/checkpoint', methods=['POST'])
def save_checkpoint():
    """Save workflow state as serialized checkpoint"""
    auth_header = request.headers.get('Authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    body = request.get_json()
    if not body or 'state' not in body:
        return jsonify({'error': 'missing state'}), 400

    state = body['state']
    serialized = base64.b64encode(pickle.dumps(state)).decode()
    signature = hashlib.sha256((serialized + SECRET_KEY).encode()).hexdigest()

    return jsonify({
        'checkpoint_state': serialized,
        'signature': signature
    }), 200

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
